% ============================================================
\section{总论：五大分解的统一视角}
% ============================================================

在 MIT 18.065 课程中，Strang 教授将矩阵分解归结为五种核心形式\cite{strang2019linear}：

\begin{enumerate}
  \item $A = LU$ —— 高斯消元的矩阵形式（下三角 × 上三角）
  \item $A = QR$ —— 正交化（正交矩阵 × 上三角）
  \item $S = Q\Lambda Q^{\T}$ —— 对称矩阵的谱分解（正交对角化）
  \item $A = X\Lambda X^{-1}$ —— 一般矩阵的对角化（特征向量基底）
  \item $A = U\Sigma V^{\T}$ —— 奇异值分解（任意矩阵的正交对角化）
\end{enumerate}

这五种分解构成了从线性方程组求解（LU）到最小二乘（QR）、到数据降维与主成分分析（SVD）的完整理论链。

\textbf{核心思想：}每一种分解本质上都是在寻找一组\textbf{好的基底}，使得矩阵在这组基底下呈现出最简单的形式——对角形或三角形。\\
\textbf{哲学：}基底变换 = 左乘/右乘可逆矩阵 → 矩阵的标准形。

% ============================================================
\section{$A = LU$：高斯消元的矩阵形式}
% ============================================================

\subsection{初等矩阵与消元操作}

\begin{definition}[初等下三角矩阵]
  设 $\mathbf{e}_k$ 为第 $k$ 个标准基向量。定义\textbf{初等下三角矩阵}：
  \begin{equation}
    E_k = I - \boldsymbol{\ell}_k \mathbf{e}_k^{\T}
  \end{equation}
  其中乘数向量 $\boldsymbol{\ell}_k = (0,\dots,0,\ell_{k+1,k},\dots,\ell_{n,k})^{\T}$，而
  \begin{equation}
    \ell_{ik} = \frac{a_{ik}^{(k-1)}}{a_{kk}^{(k-1)}}, \quad i = k+1,\dots,n
  \end{equation}
  是第 $k$ 步消元的\textbf{乘数}（multiplier）。
\end{definition}

\begin{proposition}[初等矩阵的作用]
  $E_k$ 左乘 $A^{(k-1)}$ 的效果是：将第 $k$ 列主元 $a_{kk}^{(k-1)}$ 以下的元素全部消为零。
  即：
  \begin{equation}
    E_k A^{(k-1)} = A^{(k)}
  \end{equation}
  其中 $A^{(k)}$ 的前 $k$ 列已经是上三角形式。
\end{proposition}

\textbf{关键洞察：}初等矩阵 $E_k$ 本身是下三角矩阵，其逆矩阵也极为简单：
\begin{equation}
  E_k^{-1} = I + \boldsymbol{\ell}_k \mathbf{e}_k^{\T}
\end{equation}

\textbf{Why?} 因为 $(I - \boldsymbol{\ell}_k\mathbf{e}_k^{\T})(I + \boldsymbol{\ell}_k\mathbf{e}_k^{\T}) = I - \boldsymbol{\ell}_k\mathbf{e}_k^{\T}\boldsymbol{\ell}_k\mathbf{e}_k^{\T} = I$，
而 $\mathbf{e}_k^{\T}\boldsymbol{\ell}_k = 0$（$\boldsymbol{\ell}_k$ 的前 $k$ 个分量全为零）。

\begin{remark}[逆矩阵的几何意义]
  $E_k$ 的作用是``减去某行的倍数''（消元），$E_k^{-1}$ 的作用恰好是``加回该倍数''——这正是 $L$ 
矩阵的列中填入乘数 $\ell_{ik}$ 的数学根源。
\end{remark}

\subsection{严格构造 $L$}

设消元过程需要 $n-1$ 步（从第 1 列到第 $n-1$ 列），得到：
\begin{equation}
  E_{n-1} \cdots E_2 E_1 A = U
\end{equation}
其中 $U$ 是上三角矩阵。

\textbf{构造 $L$：}将等式改写为：
\begin{equation}
  A = (E_1^{-1} E_2^{-1} \cdots E_{n-1}^{-1}) U = LU
\end{equation}
其中 $L = E_1^{-1} E_2^{-1} \cdots E_{n-1}^{-1}$。

\begin{theorem}[$L$ 的显式形式]
  在无需行交换的条件下，$L$ 具有以下显式结构：
  \begin{equation}
    L = I + \sum_{k=1}^{n-1} \boldsymbol{\ell}_k \mathbf{e}_k^{\T}
  \end{equation}
  即 $L$ 的对角线全为 1，第 $k$ 列主元以下恰好填入第 $k$ 步消元的乘数 $\ell_{ik}$。
\end{theorem}

\begin{proof}[证明要点]
  我们需要验证 $E_1^{-1} E_2^{-1} \cdots E_{n-1}^{-1} = I + \sum_{k=1}^{n-1} \boldsymbol{\ell}_k \mathbf{e}_k^{\T}$。

  关键性质：当 $i < j$ 时，$\mathbf{e}_i^{\T} \boldsymbol{\ell}_j = 0$（因为 $\boldsymbol{\ell}_j$ 的前 $j$ 个分量全为零）。

  因此：
  \begin{align}
    E_i^{-1} E_j^{-1} &= (I + \boldsymbol{\ell}_i \mathbf{e}_i^{\T})(I + \boldsymbol{\ell}_j \mathbf{e}_j^{\T}) \nonumber\\
    &= I + \boldsymbol{\ell}_i \mathbf{e}_i^{\T} + \boldsymbol{\ell}_j \mathbf{e}_j^{\T} + \boldsymbol{\ell}_i \underbrace{(\mathbf{e}_i^{\T}\boldsymbol{\ell}_j)}_{=0} \mathbf{e}_j^{\T} \nonumber\\
    &= I + \boldsymbol{\ell}_i \mathbf{e}_i^{\T} + \boldsymbol{\ell}_j \mathbf{e}_j^{\T}
  \end{align}

  交叉项为零！归纳可得所有逆矩阵的乘积恰好是各 $\boldsymbol{\ell}_k\mathbf{e}_k^{\T}$ 的和。
\end{proof}

\begin{remark}[无需显式计算 $L$]
  这正是高斯消元法的优雅之处：\textbf{不需要做任何矩阵乘法}来求 $L$。消元过程中产生的乘数 $\ell_{ik}$ 
直接按位置填入单位下三角矩阵即可。
\end{remark}

\subsection{PLU 分解：行交换的情况}

若消元过程中需要行交换（主元为零或过小），则引入置换矩阵 $P$：
\begin{equation}
  PA = LU
\end{equation}
$P$ 是初等置换矩阵的乘积，记录了所有行交换的历史。实践中，$P$ 通过部分主元选取（partial pivoting）确定。

% ============================================================
\section{$A = QR$：正交三角分解}
% ============================================================

\subsection{Gram-Schmidt：概念性构造}

设 $A = [\mathbf{a}_1 \; \mathbf{a}_2 \; \cdots \; \mathbf{a}_n] \in \R^{m \times n}$，$m \ge n$，列满秩。

\textbf{经典 Gram-Schmidt (CGS) 过程：}
\begin{align}
  \mathbf{v}_1 &= \mathbf{a}_1, & \mathbf{q}_1 &= \frac{\mathbf{v}_1}{\|\mathbf{v}_1\|} \\[4pt]
  \mathbf{v}_2 &= \mathbf{a}_2 - (\mathbf{q}_1^{\T}\mathbf{a}_2)\mathbf{q}_1, & \mathbf{q}_2 &= \frac{\mathbf{v}_2}{\|\mathbf{v}_2\|} \\[4pt]
  \mathbf{v}_3 &= \mathbf{a}_3 - (\mathbf{q}_1^{\T}\mathbf{a}_3)\mathbf{q}_1 - (\mathbf{q}_2^{\T}\mathbf{a}_3)\mathbf{q}_2, & \mathbf{q}_3 &= \frac{\mathbf{v}_3}{\|\mathbf{v}_3\|}
\end{align}

一般公式：
\begin{equation}
  \mathbf{v}_j = \mathbf{a}_j - \sum_{i=1}^{j-1} (\mathbf{q}_i^{\T}\mathbf{a}_j)\mathbf{q}_i, \qquad
  \mathbf{q}_j = \frac{\mathbf{v}_j}{\|\mathbf{v}_j\|}
\end{equation}

\textbf{$R$ 矩阵的构造：}
\begin{itemize}
  \item 对角元：$r_{jj} = \|\mathbf{v}_j\|$
  \item 非对角元：$r_{ij} = \mathbf{q}_i^{\T}\mathbf{a}_j$（$i < j$）
\end{itemize}

则 $A = QR$，其中 $Q = [\mathbf{q}_1 \cdots \mathbf{q}_n]$ 列正交规范，$R$ 上三角。

\begin{remark}[CGS 的数值问题]
  经典 Gram-Schmidt 数值不稳定——舍入误差导致 $\mathbf{q}_i$ 之间失去正交性。改进版本 Modified Gram-Schmidt (MGS) 
  有更好的数值性质，但工业界首选方法是 Householder 反射。
\end{remark}

\subsection{Householder 反射：工业标准}

\begin{definition}[Householder 矩阵]
  对任意非零向量 $\mathbf{v} \in \R^m$，Householder 矩阵定义为：
  \begin{equation}
    H = I - 2\frac{\mathbf{v}\mathbf{v}^{\T}}{\mathbf{v}^{\T}\mathbf{v}}
  \end{equation}
\end{definition}

\begin{proposition}[Householder 矩阵的性质]
  \begin{enumerate}
    \item $H$ 是对称的：$H = H^{\T}$
    \item $H$ 是正交的：$H^{\T}H = I$（即 $H^{-1} = H$）
    \item $H$ 是反射矩阵：它将任意向量关于超平面 $(\Span\{\mathbf{v}\})^{\perp}$ 做镜面反射
    \item $\|H\mathbf{x}\| = \|\mathbf{x}\|$（保范变换）
  \end{enumerate}
\end{proposition}

\begin{proof}[正交性证明]
  \begin{align}
    H^{\T}H &= \left(I - 2\frac{\mathbf{v}\mathbf{v}^{\T}}{\mathbf{v}^{\T}\mathbf{v}}\right)\left(I - 2\frac{\mathbf{v}\mathbf{v}^{\T}}{\mathbf{v}^{\T}\mathbf{v}}\right) \nonumber\\
    &= I - 4\frac{\mathbf{v}\mathbf{v}^{\T}}{\mathbf{v}^{\T}\mathbf{v}} + 4\frac{\mathbf{v}(\mathbf{v}^{\T}\mathbf{v})\mathbf{v}^{\T}}{(\mathbf{v}^{\T}\mathbf{v})^2}
    = I
  \end{align}
\end{proof}

\subsection{Householder QR 的构造算法}

\textbf{核心思想：}逐列将 $A$ 的下三角部分``反射''为零。

\textbf{第 1 步：}取 $A$ 的第一列 $\mathbf{x} = \mathbf{a}_1$。构造 $\mathbf{v}$ 使得 $H_1\mathbf{x} = \|\mathbf{x}\|\mathbf{e}_1$。

设 $\alpha = -\sign(x_1)\|\mathbf{x}\|$（此选择保证数值稳定），令：
\begin{equation}
  \mathbf{v} = \mathbf{x} - \alpha\mathbf{e}_1
\end{equation}

则 $H_1 = I - 2\frac{\mathbf{v}\mathbf{v}^{\T}}{\mathbf{v}^{\T}\mathbf{v}}$ 将第一列化为 $[\alpha, 0, \dots, 0]^{\T}$。

\textbf{第 $k$ 步：}对右下角的 $(m-k+1)\times (n-k+1)$ 子矩阵重复操作。第 $k$ 步的 Householder 矩阵形如：
\begin{equation}
  H_k = \begin{bmatrix}
    I_{k-1} & 0 \\
    0 & \tilde{H}_k
  \end{bmatrix}
\end{equation}
其中 $\tilde{H}_k$ 是作用在剩余子空间的 Householder 反射。

\textbf{最终：}
\begin{equation}
  H_n \cdots H_2 H_1 A = R \quad \Longrightarrow \quad Q^{\T} = H_n \cdots H_2 H_1
\end{equation}

由于每个 $H_k$ 都是正交对称阵，$Q = H_1 H_2 \cdots H_n$ 也是正交矩阵。

\begin{remark}[Householder vs Gram-Schmidt vs Givens]
  \begin{itemize}
    \item Gram-Schmidt：概念直观，但不稳定；适合手算小矩阵
    \item Householder：数值稳定（向后稳定），MATLAB \texttt{qr()} 的默认算法
    \item Givens 旋转：适合稀疏矩阵，可以``选择性''消零
  \end{itemize}
\end{remark}

% ============================================================
\section{$S = Q\Lambda Q^{\T}$：对称矩阵的谱分解}
% ============================================================

\subsection{谱定理}

\begin{theorem}[实对称矩阵的谱定理]
  设 $S \in \R^{n \times n}$ 为实对称矩阵（$S = S^{\T}$）。则存在正交矩阵 $Q \in \R^{n \times n}$ 和对角矩阵 
  $\Lambda = \diag(\lambda_1,\dots,\lambda_n)$，使得：
  \begin{equation}
    S = Q\Lambda Q^{\T}
  \end{equation}
  其中 $\lambda_i \in \R$ 是 $S$ 的特征值，$Q$ 的第 $i$ 列 $\mathbf{q}_i$ 是相应特征向量。
\end{theorem}

\subsection{严格构造}

\begin{enumerate}
  \item \textbf{解特征方程：}$\det(S - \lambda I) = 0$。由于 $S$ 对称，所有特征值 $\lambda_1,\dots,\lambda_n$ 
  均为\textbf{实数}（这是谱定理的核心保证）。

  \item \textbf{求特征向量：}对每个 $\lambda_i$，解齐次线性方程组：
  \begin{equation}
    (S - \lambda_i I)\mathbf{v}_i = \mathbf{0}
  \end{equation}
  得到特征向量 $\mathbf{v}_i$。

  \item \textbf{正交性验证：}
  \begin{itemize}
    \item 若 $\lambda_i \neq \lambda_j$，则 $\mathbf{v}_i$ 与 $\mathbf{v}_j$ \textbf{自动正交}。
    证明：$\lambda_i \mathbf{v}_i^{\T}\mathbf{v}_j = (S\mathbf{v}_i)^{\T}\mathbf{v}_j = \mathbf{v}_i^{\T}S\mathbf{v}_j = \mathbf{v}_i^{\T}(\lambda_j\mathbf{v}_j) = \lambda_j \mathbf{v}_i^{\T}\mathbf{v}_j$，
    因此 $(\lambda_i - \lambda_j)\mathbf{v}_i^{\T}\mathbf{v}_j = 0$，所以 $\mathbf{v}_i^{\T}\mathbf{v}_j = 0$。

    \item 若 $\lambda_i = \lambda_j$（重特征值），特征空间的维数等于代数重数（谱定理保证几何重数=代数重数），
    可在特征空间内用 Gram-Schmidt 构造正交基。
  \end{itemize}

  \item \textbf{单位化：}$\mathbf{q}_i = \dfrac{\mathbf{v}_i}{\|\mathbf{v}_i\|}$。

  \item \textbf{组装：}
  \begin{equation}
    Q = [\mathbf{q}_1 \; \mathbf{q}_2 \; \cdots \; \mathbf{q}_n], \qquad
    \Lambda = \diag(\lambda_1,\dots,\lambda_n)
  \end{equation}
\end{enumerate}

\subsection{谱分解的``秩-1展开''视角}

谱分解可以写为秩-1 对称投影的和（这是 MIT 18.065 最重要的视角之一）：
\begin{equation}
  S = \sum_{i=1}^{n} \lambda_i \, \mathbf{q}_i \mathbf{q}_i^{\T}
\end{equation}

\begin{remark}[几何意义]
  $\mathbf{q}_i\mathbf{q}_i^{\T}$ 是到 $\mathbf{q}_i$ 方向的\textbf{正交投影矩阵}。
  $S$ 将空间沿每个 $\mathbf{q}_i$ 方向拉伸 $\lambda_i$ 倍。这是理解 PCA、协方差矩阵、二次型的核心。
\end{remark}

\begin{remark}[为什么必须对称？]
  反对称矩阵（或一般矩阵）的特征向量不一定正交，甚至特征值可能是复数。谱分解之``美''来自对称性的保证。
  这是对称矩阵在应用数学中占据中心地位的根本原因。
\end{remark}

% ============================================================
\section{$A = X\Lambda X^{-1}$：一般矩阵的对角化}
% ============================================================

\subsection{对角化的条件}

\begin{theorem}[可对角化条件]
  $A \in \C^{n \times n}$ 可对角化当且仅当 $A$ 有 $n$ 个线性无关的特征向量。
\end{theorem}

\subsection{构造过程}

\begin{enumerate}
  \item \textbf{求特征值：}解 $\det(A - \lambda I) = 0$，得到特征值 $\lambda_1,\dots,\lambda_n$（可为复数）。

  \item \textbf{求特征向量：}对每个 $\lambda_i$，解 $(A - \lambda_i I)\mathbf{x}_i = \mathbf{0}$。

  \item \textbf{检验线性无关性：}若得到 $n$ 个线性无关的特征向量，则对角化可行。否则只能求 Jordan 标准型。

  \item \textbf{组装：}
  \begin{equation}
    X = [\mathbf{x}_1 \; \mathbf{x}_2 \; \cdots \; \mathbf{x}_n], \qquad
    \Lambda = \diag(\lambda_1,\dots,\lambda_n)
  \end{equation}

  \item \textbf{验证：}由于 $A\mathbf{x}_i = \lambda_i \mathbf{x}_i$，有 $AX = X\Lambda$。若 $X$ 可逆，则：
  \begin{equation}
    A = X\Lambda X^{-1}
  \end{equation}
\end{enumerate}

\subsection{与谱分解的关键区别}

\begin{center}
\begin{tabular}{p{5cm}|p{5cm}}
  \hline
  \textbf{谱分解 $S = Q\Lambda Q^{\T}$} & \textbf{对角化 $A = X\Lambda X^{-1}$} \\
  \hline
  $S$ 必须是\textbf{实对称}矩阵 & $A$ 可以是\textbf{任意}方阵 \\
  特征值为实数 & 特征值可为复数 \\
  $Q$ 是\textbf{正交}矩阵（$Q^{-1} = Q^{\T}$） & $X$ 仅是\textbf{可逆}矩阵 \\
  特征向量自动正交 & 特征向量未必正交 \\
  无需显式求逆（$Q^{\T}$ 即逆） & 需要显式计算 $X^{-1}$ \\
  \hline
\end{tabular}
\end{center}

\begin{remark}[为何谱分解更受偏爱]
  ``正交''比``可逆''更强。正交变换保范（等距），数值稳定；而一般的 $X^{-1}$ 可能病态，
  放大小误差。这就是为什么在数值线性代数中，我们尽可能使用正交变换（QR、SVD），
  而不是直接对角化。
\end{remark}

\subsection{不能对角化时：Jordan 标准型}

若几何重数 $<$ 代数重数，矩阵不可对角化。此时存在可逆矩阵 $P$ 使得：
\begin{equation}
  P^{-1}AP = J = \diag(J_{n_1}(\lambda_1), \dots, J_{n_k}(\lambda_k))
\end{equation}
其中 Jordan 块：
\begin{equation}
  J_m(\lambda) = \begin{bmatrix}
    \lambda & 1 & & \\
    & \lambda & \ddots & \\
    & & \ddots & 1 \\
    & & & \lambda
  \end{bmatrix}_{m \times m}
\end{equation}

% ============================================================
\section{$A = U\Sigma V^{\T}$：奇异值分解}
% ============================================================

\subsection{SVD 定理}

\begin{theorem}[奇异值分解]
  对任意矩阵 $A \in \R^{m \times n}$，存在正交矩阵 $U \in \R^{m \times m}$、$V \in \R^{n \times n}$ 和``对角''矩阵 
  $\Sigma \in \R^{m \times n}$ 使得：
  \begin{equation}
    A = U\Sigma V^{\T}
  \end{equation}
  其中 $\Sigma = \diag(\sigma_1,\dots,\sigma_r,0,\dots,0)$，$\sigma_1 \ge \sigma_2 \ge \cdots \ge \sigma_r > 0$，
  $r = \rank(A)$。
\end{theorem}

\begin{definition}[术语]
  \begin{itemize}
    \item $\sigma_i$：$A$ 的\textbf{奇异值}（singular value）
    \item $U$ 的列 $\mathbf{u}_i$：\textbf{左奇异向量}（left singular vector）
    \item $V$ 的列 $\mathbf{v}_i$：\textbf{右奇异向量}（right singular vector）
  \end{itemize}
\end{definition}

\subsection{构造过程：从 $A^{\T}A$ 的谱分解导出 SVD}

这是 SVD 最优雅的构造——利用了对称矩阵的谱分解定理作为工具。

\begin{proof}[SVD 的构造性证明]
  设 $A \in \R^{m \times n}$，令 $C = A^{\T}A \in \R^{n \times n}$。

  \textbf{第 1 步：对 $A^{\T}A$ 做谱分解。}

  $C = A^{\T}A$ 是\textbf{对称半正定}矩阵（$\mathbf{x}^{\T}C\mathbf{x} = \|A\mathbf{x}\|^2 \ge 0$）。
  由谱定理：
  \begin{equation}
    A^{\T}A = V\Lambda V^{\T}
  \end{equation}
  其中 $\Lambda = \diag(\lambda_1,\dots,\lambda_n)$，$\lambda_1 \ge \cdots \ge \lambda_r > 0 = \lambda_{r+1} = \cdots = \lambda_n$，
  $r = \rank(A)$。$V = [\mathbf{v}_1 \cdots \mathbf{v}_n]$ 是正交矩阵。

  \textbf{第 2 步：定义奇异值。}
  \begin{equation}
    \sigma_i = \sqrt{\lambda_i}, \quad i = 1,\dots,n
  \end{equation}
  $\sigma_1 \ge \cdots \ge \sigma_r > 0 = \sigma_{r+1} = \cdots = \sigma_n$。

  \textbf{第 3 步：构造 $\Sigma$。}
  \begin{equation}
    \Sigma = \begin{bmatrix}
      \diag(\sigma_1,\dots,\sigma_r) & 0_{r \times (n-r)} \\
      0_{(m-r) \times r} & 0_{(m-r) \times (n-r)}
    \end{bmatrix} \in \R^{m \times n}
  \end{equation}

  \textbf{第 4 步：构造左奇异向量 $\mathbf{u}_i$（$1 \le i \le r$）。}
  \begin{equation}
    \mathbf{u}_i = \frac{1}{\sigma_i} A\mathbf{v}_i \in \R^m, \quad i = 1,\dots,r
  \end{equation}

  验证正交归一性：
  \begin{align}
    \mathbf{u}_i^{\T}\mathbf{u}_j &= \frac{1}{\sigma_i\sigma_j} (A\mathbf{v}_i)^{\T}(A\mathbf{v}_j)
    = \frac{1}{\sigma_i\sigma_j} \mathbf{v}_i^{\T}(A^{\T}A\mathbf{v}_j) \nonumber\\
    &= \frac{1}{\sigma_i\sigma_j} \mathbf{v}_i^{\T}(\lambda_j\mathbf{v}_j)
    = \frac{\sigma_j^2}{\sigma_i\sigma_j} \mathbf{v}_i^{\T}\mathbf{v}_j
    = \begin{cases} 1 & i = j \\ 0 & i \neq j \end{cases}
  \end{align}

  \textbf{第 5 步：补全 $U$。}若 $r < m$，选取 $\mathbf{u}_{r+1},\dots,\mathbf{u}_m$ 构成 $\Null(A^{\T})$ 
  的标准正交基（即 $A^{\T}\mathbf{u}_i = \mathbf{0}$），使 $U = [\mathbf{u}_1 \cdots \mathbf{u}_m]$ 为正交矩阵。

  \textbf{第 6 步：验证 $A = U\Sigma V^{\T}$。}

  等价于验证 $AV = U\Sigma$，即考察每一列：
  \begin{itemize}
    \item 对 $1 \le i \le r$：$A\mathbf{v}_i = \sigma_i\mathbf{u}_i$ —— 由第 4 步构造直接成立。
    \item 对 $r < i \le n$：由于 $\lambda_i = 0$，
    $\|A\mathbf{v}_i\|^2 = \mathbf{v}_i^{\T}A^{\T}A\mathbf{v}_i = \mathbf{v}_i^{\T}(\lambda_i\mathbf{v}_i) = 0$，
    所以 $A\mathbf{v}_i = \mathbf{0}$。
  \end{itemize}

  因此 $AV = U\Sigma$，两边右乘 $V^{\T}$ 得 $A = U\Sigma V^{\T}$。\hfill $\square$
\end{proof}

\subsection{SVD 的核心洞察}

\begin{enumerate}
  \item \textbf{$A^{\T}A$ 和 $AA^{\T}$ 的谱分解是同一个东西在不同空间的表现。}
  $A^{\T}A$ 的特征值 = $AA^{\T}$ 的特征值 = $\sigma_i^2$，$V$ 的列是 $A^{\T}A$ 的特征向量，$U$ 的列是 $AA^{\T}$ 的特征向量。

  \item \textbf{SVD 是``正交对角化''向非方阵的推广。}
  对称矩阵的谱分解 $S = Q\Lambda Q^{\T}$ 中，左右正交矩阵相同（$Q$）。
  SVD = 非对称矩阵的谱分解，需要两组不同的正交基：$U$（定义域）和 $V$（值域）。

  \item \textbf{秩-1 展开（Eckart-Young 定理的基础）：}
  \begin{equation}
    A = \sum_{i=1}^{r} \sigma_i \, \mathbf{u}_i \mathbf{v}_i^{\T}
  \end{equation}
  每项是秩-1 矩阵。$\sigma_1$ 最大 → $\sigma_1\mathbf{u}_1\mathbf{v}_1^{\T}$ 是 $A$ 的``最佳秩-1 逼近''。

  截断到前 $k$ 项给出\textbf{最佳秩-$k$ 逼近}：$\|A - A_k\|_2 = \sigma_{k+1}$。
\end{enumerate}

\subsection{三种 SVD 形式（MIT 18.065 术语）}

\begin{center}
\begin{tabular}{l|l|l}
  \hline
  \textbf{形式} & \textbf{尺寸} & \textbf{用途} \\
  \hline
  完全 SVD & $A = U_{m \times m}\Sigma_{m \times n}V_{n \times n}^{\T}$ & 理论分析 \\
  紧致 SVD & $A = U_r \Sigma_r V_r^{\T}$ & $\rank(A)=r$，去掉零奇异值 \\
  经济 SVD & $A = \hat{U}\hat{\Sigma}V^{\T}$（$m \gg n$） & 计算输出（MATLAB \texttt{svd(A,'econ')}）\\
  \hline
\end{tabular}
\end{center}

\begin{remark}[SVD 的数值计算]
  实际计算 SVD 不使用上述的``先算 $A^{\T}A$ 再谱分解''方法——这会导致条件数平方（$\cond(A^{\T}A) = \cond(A)^2$），
  数值不稳定。工业上使用 Golub-Reinsch 算法：先通过 Householder 反射做双对角化，
  再用隐式 QR 迭代（Golub-Kahan SVD）求奇异值。这超出了本教程范围。
\end{remark}

